// Builds auto-generated tag collections from the books data.
// A tag qualifies for its own collection page when enough books carry it.
// Pure function of (books, options) so it is unit-testable; the Eleventy
// data file (src/_data/collectionConfigs.js) wires it to books.csv and
// dedupes against curated configs and legacy static pages.

const THRESHOLD = 15;

// alias (lowercase) -> canonical display name. Merges near-duplicate tags
// without touching books.csv. A book tagged with any variant appears in the
// canonical collection.
const TAG_ALIASES = {
  'appropriation': 'Appropriation Art',
  'contemporary': 'Contemporary Art',
  'documentary photography': 'Documentary',
};

function slugifyTag(name) {
  return name
    .toLowerCase()
    .replace(/['’]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

// Same date priority as the old dynamicCollections enrichment:
// numeric accession year first, publication year as fallback.
function bookDate(book) {
  const a = parseInt(book.accession_no, 10);
  if (!isNaN(a)) return a;
  const y = parseInt(book.publication_year, 10);
  return isNaN(y) ? 0 : y;
}

function hasCover(book) {
  return book.image_url && book.image_url !== 'NULL' && book.image_url.trim() !== '';
}

function buildTagCollections(books, options = {}) {
  const threshold = options.threshold || THRESHOLD;
  const aliases = options.aliases || TAG_ALIASES;

  // key (lowercase canonical) -> { books: Set-deduped list, casings: Counter, sourceTags: Set }
  const groups = new Map();

  books.forEach(book => {
    const seen = new Set();
    (book.tags || '').split(',').forEach(raw => {
      const tag = raw.trim();
      if (!tag) return;
      const canonicalDisplay = aliases[tag.toLowerCase()] || tag;
      const key = canonicalDisplay.toLowerCase();
      if (!groups.has(key)) {
        groups.set(key, { books: [], casings: new Map(), sourceTags: new Set() });
      }
      const g = groups.get(key);
      g.sourceTags.add(tag);
      if (!aliases[tag.toLowerCase()]) {
        g.casings.set(tag, (g.casings.get(tag) || 0) + 1);
      }
      // A book tagged with two variants of the same canonical tag counts once.
      if (!seen.has(key)) {
        seen.add(key);
        g.books.push(book);
      }
    });
  });

  const collections = [];
  groups.forEach((g, key) => {
    if (g.books.length < threshold) return;

    // Display name: alias target if aliased, else the most frequent casing.
    let display = aliases[key] || null;
    if (!display) {
      let best = 0;
      g.casings.forEach((count, casing) => {
        if (count > best) { best = count; display = casing; }
      });
      if (!display) display = key;
    }

    const sorted = [...g.books].sort((a, b) => bookDate(b) - bookDate(a));
    const withCover = sorted.find(hasCover);
    const sourceTags = [...g.sourceTags];

    collections.push({
      slug: slugifyTag(display),
      title: display,
      description: `Every book in the library tagged “${display}.”`,
      matchBy: { tag: sourceTags },
      sourceTags,
      sortBy: 'authorAsc',
      coversFirst: true,
      bookCount: g.books.length,
      image: withCover ? withCover.image_url : null,
      featured: false,
      category: 'subject',
      autoGenerated: true,
    });
  });

  return collections.sort((a, b) => b.bookCount - a.bookCount);
}

module.exports = { buildTagCollections, slugifyTag, TAG_ALIASES, THRESHOLD };
